export const mcpDefinitions=[
 ["GetClient","keyClient","Read a client using its identifier."],
 ["GetInvoice","keyFacture","Read a sales invoice using its identifier, including lines and tax totals."],
 ["GetShipment","keyDossier","Read an expedition dossier using its identifier, including packages and status."],
 ["GetBooking","keyBooking","Read a booking using its identifier, including equipment and packages."]
].map(([name,key,description])=>({name,description,inputSchema:{type:"object",properties:{[key]:{type:"string",description:"Identifiant de la ressource.",minLength:1,maxLength:256,pattern:"^(?=.*\\S)[^\\u0000-\\u001F\\u007F-\\u009F]+$"}},required:[key],additionalProperties:false},annotations:{readOnlyHint:true,destructiveHint:false,idempotentHint:true,openWorldHint:false}}));
mcpDefinitions.push({name:"GetTracking",description:"Read the latest tracking events for an entity, most recent first. An empty array means no visible events.",inputSchema:{type:"object",properties:{entity:{type:"string",description:"Tracked entity kind. Use Dossier for a shipment.",enum:["Client","Booking","Dossier","Voyage","Facture","Reglement","Cotation"]},entityKey:{type:"string",minLength:1,maxLength:256},take:{type:"integer",minimum:1,maximum:500,default:100}},required:["entity","entityKey"],additionalProperties:false}});
export const rpcReply=(id,result,{sse=false}={})=>new Response(sse?`: ping\r\n\r\nevent: message\r\ndata: ${JSON.stringify({jsonrpc:"2.0",id,result})}\r\n\r\n`:JSON.stringify({jsonrpc:"2.0",id,result}),{status:200,headers:{"Content-Type":sse?"text/event-stream; charset=utf-8":"application/json"}});
export const mcpRequest=(definitions=mcpDefinitions,{sse=false}={})=>async(url,options)=>{const message=JSON.parse(options.body);if(message.method==="initialize")return rpcReply(message.id,{protocolVersion:"2025-11-25",capabilities:{tools:{}},serverInfo:{name:"Logistics",version:"1.0.0"}},{sse});if(message.method==="notifications/initialized")return new Response(null,{status:202});if(message.method==="tools/list")return rpcReply(message.id,{tools:definitions},{sse});throw new Error("Unexpected execution request");};
